/// 4120u^13 + 528u^14 + 32u^15, the result's unit error (header), rounded up to an `f64`:
/// 7599824371187737 · 2^-95.
const ERROR: f64 = f64::from_bits(0x3d4b_0000_0000_0019);

/// `line_cone`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, f: P3, s: i128, t: i128) -> Option<Sign> {
    let d_x = exact_f64(b.x) - exact_f64(a.x);
    let d_y = exact_f64(b.y) - exact_f64(a.y);
    let d_z = exact_f64(b.z) - exact_f64(a.z);
    let e_x = exact_f64(f.x) - exact_f64(c.x);
    let e_y = exact_f64(f.y) - exact_f64(c.y);
    let e_z = exact_f64(f.z) - exact_f64(c.z);
    let w_x = exact_f64(a.x) - exact_f64(c.x);
    let w_y = exact_f64(a.y) - exact_f64(c.y);
    let w_z = exact_f64(a.z) - exact_f64(c.z);
    let n_x_1 = w_y * d_z;
    let n_x_2 = w_z * d_y;
    let n_x = n_x_1 - n_x_2;
    let n_y_1 = w_z * d_x;
    let n_y_2 = w_x * d_z;
    let n_y = n_y_1 - n_y_2;
    let n_z_1 = w_x * d_y;
    let n_z_2 = w_y * d_x;
    let n_z = n_z_1 - n_z_2;
    let nn_1 = n_x * n_x;
    let nn_2 = n_y * n_y;
    let nn_3 = nn_1 + nn_2;
    let nn_4 = n_z * n_z;
    let nn = nn_3 + nn_4;
    let ee_1 = e_x * e_x;
    let ee_2 = e_y * e_y;
    let ee_3 = ee_1 + ee_2;
    let ee_4 = e_z * e_z;
    let ee = ee_3 + ee_4;
    let en_1 = e_x * n_x;
    let en_2 = e_y * n_y;
    let en_3 = en_1 + en_2;
    let en_4 = e_z * n_z;
    let en = en_3 + en_4;
    let s = rounded_f64(s, 40)?;
    let ss = s * s;
    let delta_1 = ss * ee;
    let delta_2 = delta_1 * nn;
    let t = rounded_f64(t, 40)?;
    let delta_3 = t * t;
    let delta_4 = ss + delta_3;
    let delta_5 = delta_4 * en;
    let delta_6 = delta_5 * en;
    let delta = delta_2 - delta_6;
    let m_x = largest_magnitude([d_x, e_x, w_x]);
    let m_y = largest_magnitude([d_y, e_y, w_y]);
    let m_z = largest_magnitude([d_z, e_z, w_z]);
    let m_slope = largest_magnitude([s, t]);
    let scale = m_y * m_y * m_z * m_z * m_z * m_z;
    let scale = larger(scale, m_y * m_y * m_y * m_y * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_z * m_z * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y * m_y * m_y);
    let scale = larger(scale, m_x * m_x * m_x * m_x * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_x * m_x * m_y * m_y);
    let scale = m_slope * m_slope * scale;
    decide(delta, ERROR, scale)
}

